sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    //Type appropriate comment here, and begin script below
    var utils = new GlideAjax('global.GlobalGroupUtils');
    utils.addParam('sysparm_name', 'getGroupManager');
    utils.addParam('sysparm_group_id', newValue);
    utils.getXMLAnswer(function(answer) {
        console.log('====1111====' + answer);
        if (answer) {
            g_form.setValue('asign_to', answer);
        }

    });
    //    utils.getXML(function(response) {
    //       var managerId = response.responseXML.documentElement.getAttribute('answer');
    //       console.log('====1111====' + managerId);
    //       if (managerId) {
    // 		g_form.setValue('assigned_to', managerId);
    //       }
    //    });
}
